fn is_ascii_letter(c: char) -> bool {
    // Returns true if c is an ASCII letter: 'a'..'z' or 'A'..'Z'
    ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z')
}

fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Interpret txt as a sequence of chars (Unicode scalar values)
    // Return true if and only if:
    //  - the string is non-empty;
    //  - the last character is an ASCII letter;
    //  - the string has exactly one char, or the char before last is a space.
    let chars: Vec<char> = txt.chars().collect();

    if chars.len() == 0 {
        return false;
    }

    let last = chars[chars.len() - 1];
    if !is_ascii_letter(last) {
        return false;
    }

    if chars.len() == 1 {
        return true;
    }

    let before_last = chars[chars.len() - 2];
    before_last == ' '
}

